mapper.select:
SELECT id, product_id, qty, reason, ref_type, ref_id, reversal_of,
       balance_after, note, created_by, created_at
FROM stock_movement
WHERE ref_type = #{refType} AND ref_id = #{refId}
AND reason = #{reason}
ORDER BY id

SELECT id, product_id, qty, reason, ref_type, ref_id, reversal_of,
       balance_after, note, created_by, created_at
FROM stock_movement
WHERE product_id = #{productId}
ORDER BY id DESC
LIMIT #{limit}
